#!/bin/bash

cat << EOF
module Klas.SPMM

// THIS FILE IS AUTOMATICALLY GENERATED BY A SCRIPT, DO NOT EDIT

#lang-pulse
open Kuiper
open Klas.SPMM.Inst

// One single u32 variant for the test
let spmm_u32 = inst u32 128sz 128sz 32sz

// A fixed-name f32 variant for the test and quick benching
let spmm_f32 = inst f32 512sz 512sz 64sz

// Mixed-precision variants use explicit input and output conversions.
open Kuiper.Float.Casts

let g_spmm_f16_f16_f32_f32_32x32x4 =
  ginst f16 f16 f32 f32 (fcast #f16 #f32) (fcast #f16 #f32) (fun x -> x) (fun x -> x)
    (fun _ sum -> fcast #f32 #f32 sum) (fun _ sum -> sum) 32sz 32sz 4sz
let g_spmm_f16_f16_f32_f32_32x32x4_on =
  ginst_on f16 f16 f32 f32 (fcast #f16 #f32) (fcast #f16 #f32) (fun x -> x) (fun x -> x)
    (fun _ sum -> fcast #f32 #f32 sum) (fun _ sum -> sum) 32sz 32sz 4sz
let g_spmm_bf16_bf16_f32_f32_32x32x4 =
  ginst bf16 bf16 f32 f32 (fcast #bf16 #f32) (fcast #bf16 #f32) (fun x -> x) (fun x -> x)
    (fun _ sum -> fcast #f32 #f32 sum) (fun _ sum -> sum) 32sz 32sz 4sz
let g_spmm_bf16_bf16_f32_f32_32x32x4_on =
  ginst_on bf16 bf16 f32 f32 (fcast #bf16 #f32) (fcast #bf16 #f32) (fun x -> x) (fun x -> x)
    (fun _ sum -> fcast #f32 #f32 sum) (fun _ sum -> sum) 32sz 32sz 4sz
let g_spmm_f16_f32_f16_f32_32x32x4 =
  ginst f16 f32 f16 f32 (fcast #f16 #f32) (fcast #f32 #f32) (fun x -> x) (fun x -> x)
    (fun _ sum -> fcast #f32 #f16 sum) (fun _ sum -> sum) 32sz 32sz 4sz
let g_spmm_f16_f32_f16_f32_32x32x4_on =
  ginst_on f16 f32 f16 f32 (fcast #f16 #f32) (fcast #f32 #f32) (fun x -> x) (fun x -> x)
    (fun _ sum -> fcast #f32 #f16 sum) (fun _ sum -> sum) 32sz 32sz 4sz
let g_spmm_f16_bf16_f32_f64_32x32x4 =
  ginst f16 bf16 f32 f64 (fcast #f16 #f64) (fcast #bf16 #f64) (fun x -> x) (fun x -> x)
    (fun _ sum -> fcast #f64 #f32 sum) (fun _ sum -> sum) 32sz 32sz 4sz
let g_spmm_f16_bf16_f32_f64_32x32x4_on =
  ginst_on f16 bf16 f32 f64 (fcast #f16 #f64) (fcast #bf16 #f64) (fun x -> x) (fun x -> x)
    (fun _ sum -> fcast #f64 #f32 sum) (fun _ sum -> sum) 32sz 32sz 4sz
let g_spmm_f16_f32_f32_f64_32x32x4 =
  ginst f16 f32 f32 f64 (fcast #f16 #f64) (fcast #f32 #f64) (fun x -> x) (fun x -> x)
    (fun _ sum -> fcast #f64 #f32 sum) (fun _ sum -> sum) 32sz 32sz 4sz
let g_spmm_f16_f32_f32_f64_32x32x4_on =
  ginst_on f16 f32 f32 f64 (fcast #f16 #f64) (fcast #f32 #f64) (fun x -> x) (fun x -> x)
    (fun _ sum -> fcast #f64 #f32 sum) (fun _ sum -> sum) 32sz 32sz 4sz

// Fused input maps and a GEMM epilogue with runtime alpha and beta.
module MS = Kuiper.Spec.GEMM
inline_for_extraction noextract
let mapped_a (x : f16) : f32 = let y = fcast #f16 #f32 x in add y y
inline_for_extraction noextract
let mapped_b (x : f32) : f32 = add x one
let mapped_a_ok (x : f16) (r : real)
  : Lemma (requires x %~ r) (ensures mapped_a x %~ (r +. r))
    [SMTPat (mapped_a x %~ (r +. r))]
  = fcast_approx #f16 #f32 x r;
    a_add (fcast #f16 #f32 x) (fcast #f16 #f32 x) r r
let mapped_b_ok (x : f32) (r : real)
  : Lemma (requires x %~ r) (ensures mapped_b x %~ (r +. 1.0R))
    [SMTPat (mapped_b x %~ (r +. 1.0R))]
  = a_add x (one #f32) r 1.0R
let g_spmm_mapped_f16_f32_f16_f32_32x32x4 (alpha beta : f32) =
  ginst f16 f32 f16 f32 mapped_a mapped_b
    (fun x -> x +. x) (fun x -> x +. 1.0R)
    (MS.lincomb_to #f32 #f16 alpha beta)
    (MS.rlincomb (to_real alpha) (to_real beta)) 32sz 32sz 4sz
let g_spmm_mapped_f16_f32_f16_f32_32x32x4_on (alpha beta : f32) =
  ginst_on f16 f32 f16 f32 mapped_a mapped_b
    (fun x -> x +. x) (fun x -> x +. 1.0R)
    (MS.lincomb_to #f32 #f16 alpha beta)
    (MS.rlincomb (to_real alpha) (to_real beta)) 32sz 32sz 4sz

// Sputnik's f32 dispatcher uses 8, 16, 32, and 64-wide output tiles.
let g_spmm_f32_32x4x1 = inst f32 32sz 4sz 1sz
let g_spmm_f32_32x8x2 = inst f32 32sz 8sz 2sz
let g_spmm_f32_32x16x4 = inst f32 32sz 16sz 4sz
let g_spmm_f32_32x32x8 = inst f32 32sz 32sz 8sz
let g_spmm_f32_32x64x8 = inst f32 32sz 64sz 8sz

// Asynchronous, stream-parametric twins of the above. These take a stream and
// return without synchronizing, so a caller can issue many SpMMs into one
// stream and wait once -- the model Sputnik's CudaSpmm uses. See
// Kuiper.Sparse.SPMM.spmm_on.
let g_spmm_f32_32x4x1_on = inst_on f32 32sz 4sz 1sz
let g_spmm_f32_32x8x2_on = inst_on f32 32sz 8sz 2sz
let g_spmm_f32_32x16x4_on = inst_on f32 32sz 16sz 4sz
let g_spmm_f32_32x32x8_on = inst_on f32 32sz 32sz 8sz
let g_spmm_f32_32x64x8_on = inst_on f32 32sz 64sz 8sz

EOF

# let spmm_u32 = inst u32 128sz 128sz 32sz
# let spmm_f32 = inst f32 128sz 128sz 32sz

# Tweak these lists to control which instances are generated
all_blockItemsX="16 32 64 128 256 512"
all_blockItemsK="16 32 64 128 256 512"
all_blockWidth="16 32 64 128 256 512"

for blockItemsK in $all_blockItemsK; do
  for blockItemsX in $all_blockItemsX; do
    for blockWidth in $all_blockWidth; do
      if [ $((blockItemsK % blockWidth)) -ne 0 ]; then continue; fi
      if [ $((blockItemsX % blockWidth)) -ne 0 ]; then continue; fi
      if [ $(( (blockItemsK / blockWidth) % 4 )) -ne 0 ]; then continue; fi
      if [ $(( (blockItemsX / blockWidth) % 4 )) -ne 0 ]; then continue; fi
      echo "let g_spmm_f32_${blockItemsK}x${blockItemsX}x${blockWidth} = inst f32 ${blockItemsK}sz ${blockItemsX}sz ${blockWidth}sz"
      echo "let g_spmm_f32_${blockItemsK}x${blockItemsX}x${blockWidth}_on = inst_on f32 ${blockItemsK}sz ${blockItemsX}sz ${blockWidth}sz"
    done
  done
done

cat << EOF

open Kuiper.Sparse
open Kuiper.Sparse.Approx
module SZ = Kuiper.SizeT
open Kuiper.Tensor
open Kuiper.Tensor.Layout.Alg { l2_row_major as rm }
open Kuiper.EMatrix
module MS = Kuiper.Spec.GEMM

// Expose the concrete vector width to the dispatcher proof.
let chunk_f32_is_four () : Lemma (Kuiper.Array.Vectorized.chunk f32 == 4sz) =
  assert_norm (Kuiper.Array.Vectorized.chunk f32 == 4sz)

// Keep the existing aligned-tile dispatch policy and float4-wide fallback.
// Direct instantiations also support partial tiles when 4 divides cols.
fn spmm_f32_dispatch
  (rows shared cols : szp)
  (gA : csr_matrix f32 (SZ.v rows) (SZ.v shared){is_global gA})
  (#_ : squash (aligned 16 gA.elems /\ aligned 16 gA.col_ind))
  (#fA : perm)
  (row_indices : larray sz rows)
  (fri : perm)
  (gB : array2 f32 (rm shared cols) { is_global gB})
  (#_ : squash (aligned 16 (core gB)))
  (#fB : perm)
  (gC : array2 f32 (rm rows cols) { is_global gC})
  (#_ : squash (aligned 16 (core gC)))
  (#eA : chest2 f32 rows shared)
  (#rA : chest2 real rows shared)
  (row_perm : permutation (natlt rows))
  (#eB : chest2 f32 shared cols)
  (#rB : chest2 real shared cols)
  (#eC : chest2 f32 rows cols)
  norewrite
  preserves
    cpu **
    on gpu_loc (csr_matrix_approx gA #fA eA rA) **
    on gpu_loc (row_indices |-> Frac fri (ordering row_perm)) **
    on gpu_loc (gB |-> Frac fB eB)
  requires
    pure (eB %~ rB) **
    pure (4 /? cols) **
    on gpu_loc (live gC) **
    pure (
      rows * (cols \`divup\` 2) <= max_blocks /\\
      rows * (cols \`divup\` 4) <= max_blocks /\\
      rows * (cols \`divup\` 8) <= max_blocks /\\
      rows * (cols \`divup\` 16) <= max_blocks /\\
      rows * (cols \`divup\` 32) <= max_blocks /\\
      rows * (cols \`divup\` 64) <= max_blocks /\\
      rows < 10000 /\\
      shared < 10000 /\\
      cols < 10000
    ) **
    pure (8 <= max_threads)
  ensures on gpu_loc (matrix_approx gC (MS.matmul rA rB))
{
  chunk_f32_is_four ();
  assert pure (Kuiper.Array.Vectorized.chunk f32 /? cols);
  if (cols %^ 64sz = 0sz) {
    lemma_divides_mod 64 (SZ.v cols);
    g_spmm_f32_32x64x8 rows shared cols gA row_indices fri gB gC
      #_ #eA #rA row_perm #eB #rB #eC;
  } else if (cols %^ 32sz = 0sz) {
    lemma_divides_mod 32 (SZ.v cols);
    g_spmm_f32_32x32x8 rows shared cols gA row_indices fri gB gC
      #_ #eA #rA row_perm #eB #rB #eC;
  } else if (cols %^ 16sz = 0sz) {
    lemma_divides_mod 16 (SZ.v cols);
    g_spmm_f32_32x16x4 rows shared cols gA row_indices fri gB gC
      #_ #eA #rA row_perm #eB #rB #eC;
  } else if (cols %^ 8sz = 0sz) {
    lemma_divides_mod 8 (SZ.v cols);
    g_spmm_f32_32x8x2 rows shared cols gA row_indices fri gB gC
      #_ #eA #rA row_perm #eB #rB #eC;
  } else {
    g_spmm_f32_32x4x1 rows shared cols gA row_indices fri gB gC
      #_ #eA #rA row_perm #eB #rB #eC;
  }
}
EOF
